D={
81142:("near / far / go straight","Para se localizar: **near, far, go straight, turn left/right**.",[("It is {{near}} the square.","Fica perto da praça."),("{{Go straight}}, then {{turn left}}.","Siga em frente e depois vire à esquerda."),("Is it {{far}} from here?","Fica longe daqui?"),("Do you have a {{tip}} for me?","Você tem uma dica para mim?")],"“It's far” significa…",["Fica perto.","Fica longe.","Está fechado."],1,"Far = longe."),
81143:("ago: há tempos","**Ago** vem depois da duração e fala do passado: *I arrived two days ago.*",[("I arrived {{two days ago}}.","Cheguei há dois dias."),("The weather {{is}} great.","O tempo está ótimo."),("I {{miss}} you a lot.","Sinto muito a sua falta."),("I wrote this card {{an hour ago}}.","Escrevi este cartão há uma hora.")],"Complete: “I got here three days ___.”",["before","ago","past"],1,"Ago depois da duração."),
81144:("past continuous","**Was/were + verbo-ing** para algo que estava acontecendo: *We were walking on the beach.*",[("We {{were walking}} on the beach.","Estávamos caminhando na praia."),("I {{was sailing}} then.","Eu estava navegando naquela hora."),("The kids {{were singing}}.","As crianças estavam cantando."),("Look at these {{photos}}!","Olhe estas fotos!")],"Complete: “She ___ reading.”",["was","were","are"],0,"She usa was."),
81145:("Have you ever…?","Experiências: **have/has + particípio**. *Ever* nas perguntas, *never* nas negativas.",[("{{Have you ever}} seen snow?","Você já viu neve?"),("I have {{never seen}} snow.","Nunca vi neve."),("She {{has visited}} Tokyo.","Ela já visitou Tóquio."),("I have {{tried}} sushi.","Já experimentei sushi.")],"Qual é o particípio de “see”?",["saw","seen","seed"],1,"See, saw, seen."),
81146:("been to × gone to","**Been to** = foi e voltou. **Gone to** = foi e ainda está lá.",[("I have {{been to}} Japan.","Já estive no Japão."),("She has {{gone to}} the store.","Ela foi à loja (e ainda está lá)."),("He has {{climbed}} a mountain.","Ele já escalou uma montanha."),("I have {{lived}} in three cities.","Já morei em três cidades.")],"“She has gone to Rome” quer dizer…",["Ela já voltou de Roma.","Ela está em Roma agora.","Ela nunca foi a Roma."],1,"Gone to = ainda lá."),
81147:("just / already / yet","**Just** = acabou de; **already** = já (afirmativa); **yet** = ainda/já (perguntas e negativas).",[("I have {{just}} finished.","Acabei de terminar."),("She has {{already}} arrived.","Ela já chegou."),("Have you finished {{yet}}?","Você já terminou?"),("Not {{yet}}.","Ainda não.")],"Complete: “I haven't eaten ___.”",["already","yet","just"],1,"Na negativa: yet."),
920021:("too × enough","**Too** vem antes do adjetivo; **enough** vem depois.",[("It is {{too}} hot for me.","Está quente demais para mim."),("It is big {{enough}} for me.","É grande o bastante para mim."),("It is not warm {{enough}}.","Não está quente o suficiente."),("The soup is {{too}} cold.","A sopa está fria demais.")],"Qual está certa?",["enough big","big enough","enough of big"],1,"Adjetivo + enough."),
81148:("for × since","**For** + duração; **since** + ponto no tempo.",[("I slept {{for}} twenty years.","Dormi por vinte anos."),("I have lived here {{since}} 1990.","Moro aqui desde 1990."),("It has been twenty years {{now}}.","Já se passaram vinte anos."),("We have been friends {{since}} spring.","Somos amigos desde a primavera.")],"Complete: “I've worked here ___ 2019.”",["for","since","ago"],1,"Ponto no tempo: since."),
81149:("Notícias recentes","**Have/has + particípio** dá notícia recente: *Sam has won a prize!*",[("I {{have}} good news!","Tenho boas notícias!"),("Sam {{has won}} a prize!","O Sam ganhou um prêmio!"),("{{What has happened}}?","O que aconteceu?"),("{{Guess}} what!","Adivinha só!")],"Qual é o particípio de “win”?",["wined","won","wan"],1,"Win, won, won."),
81150:("get + adjetivo","**Get + adjetivo** mostra mudança: *get cold, get tired, get better*.",[("They will {{get married}} in June.","Eles vão se casar em junho."),("It will {{get cold}} tonight.","Vai esfriar esta noite."),("I hope you {{get better}} soon.","Espero que você melhore logo."),("I {{get tired}} after work.","Fico cansado depois do trabalho.")],"“It gets dark” quer dizer…",["Escurece.","Clareia.","Fica quente."],0,"Get dark = escurecer."),
81151:("used to","**Used to + verbo** fala de hábitos do passado que acabaram.",[("I {{used to play}} outside.","Eu costumava brincar lá fora."),("{{Every summer}} we went to the beach.","Todo verão íamos à praia."),("{{When I was ten}}, I had a bike.","Quando eu tinha dez anos, tinha uma bicicleta."),("We {{used to}} walk to school.","Íamos a pé para a escola.")],"Qual está certa?",["I used to plays.","I used to play.","I use to played."],1,"Used to + verbo base."),
81152:("used to + passado","**Used to** + verbo: o que fazíamos sempre. **Had to** = tinha que.",[("I {{used to have}} many toys.","Eu costumava ter muitos brinquedos."),("My neighbor {{was}} my best friend.","Meu vizinho era meu melhor amigo."),("We {{used to climb}} trees.","Costumávamos subir em árvores."),("We {{had to}} paint the fence.","Tínhamos de pintar a cerca.")],"“Had to” significa…",["tinha que","podia","queria"],0,"Had to = obrigação no passado."),
81153:("Passado × presente","Compare **before** (passado) e **now** (presente).",[("{{Before}}, I was lonely.","Antes, eu era solitário."),("{{Now}}, I have many friends.","Agora, tenho muitos amigos."),("Life is {{different}} now.","A vida é diferente agora."),("I {{used to be}} shy, but I'm not now.","Eu era tímido, mas agora não sou.")],"Qual palavra marca o passado?",["now","before","today"],1,"Before aponta para o passado."),
81154:("Superlativos","**The + adjetivo-est**; adjetivos longos: **the most**.",[("This is {{the best}} book.","Este é o melhor livro."),("The cheetah is {{the fastest}} animal.","O guepardo é o animal mais rápido."),("She is {{the oldest}} person here.","Ela é a pessoa mais velha aqui."),("It is {{the most beautiful}} place.","É o lugar mais bonito.")],"Qual é o superlativo de “good”?",["the goodest","the best","the most good"],1,"Good → best."),
920022:("did / didn't + verbo base","Depois de **did** e **didn't**, o verbo fica na **forma base**.",[("{{Did you see}} him?","Você o viu?"),("I {{didn't see}} anyone.","Não vi ninguém."),("Yes, I {{did}}, last night.","Sim, vi, ontem à noite."),("{{Did she open}} the window?","Ela abriu a janela?")],"Qual está certa?",["I didn't saw him.","I didn't see him.","I not see him."],1,"Didn't + verbo base."),
81155:("the tallest","O maior: **the + adjetivo-est**. Andares: **on the tenth floor**.",[("This is {{the tallest}} building.","Este é o prédio mais alto."),("We live {{on}} the tenth floor.","Moramos no décimo andar."),("Take the {{elevator}}, please.","Pegue o elevador, por favor."),("The {{view}} from the top is great.","A vista lá de cima é ótima.")],"Complete: “She lives ___ the fifth floor.”",["in","on","at"],1,"Andar: on the … floor."),
81156:("more … than / -er than","Adjetivos longos: **more + adjetivo + than**; curtos: **-er than**.",[("London is {{bigger than}} Paris.","Londres é maior que Paris."),("Paris is {{more crowded than}} my town.","Paris é mais cheia que minha cidade."),("The buses are {{cheaper}} here.","Os ônibus são mais baratos aqui."),("This place is {{quieter than}} that one.","Este lugar é mais calmo que aquele.")],"Qual está certa?",["more big than","bigger than","biger than"],1,"Big → bigger."),
81157:("as … as","**As + adjetivo + as** = igual. **Not as … as** = menos.",[("I am {{as tall as}} you.","Sou tão alto quanto você."),("We are {{the same}} age.","Temos a mesma idade."),("She is {{not as fast as}} him.","Ela não é tão rápida quanto ele."),("We are {{different}} in many ways.","Somos diferentes em muitos aspectos.")],"Complete: “He is ___ strong as me.”",["as","like","than"],0,"as … as."),
81158:("too / enough","**Too + adjetivo** = demais; **adjetivo + enough** = suficiente.",[("This chair is {{too big}}.","Esta cadeira é grande demais."),("It is {{not big enough}}.","Não é grande o suficiente."),("This one is {{just right}}.","Esta é a ideal."),("It's {{comfortable enough}}.","É confortável o bastante.")],"Qual diz que algo é demais?",["too small","small enough","very small"],0,"Too = excesso."),
81159:("going to","**Am/is/are going to + verbo** para planos.",[("I'm {{going to rest}}.","Vou descansar."),("We are {{going to wait}} here.","Vamos esperar aqui."),("{{Let's}} meet at noon.","Vamos nos encontrar ao meio-dia."),("{{Maybe}} we will go out.","Talvez a gente saia.")],"Qual está certa?",["I going to rest.","I'm going to rest.","I'm go to rest."],1,"Am + going to + verbo."),
81160:("going to × will","**Going to** = plano pensado; **will** = decisão na hora ou previsão.",[("Tomorrow we {{are going to visit}} the museum.","Amanhã vamos visitar o museu."),("I think I {{will rest}} on Sunday.","Acho que vou descansar no domingo."),("There {{is}} a parade downtown.","Há um desfile no centro."),("We {{are going to}} have lunch there.","Vamos almoçar lá.")],"Qual mostra um plano?",["I'm going to visit Rome.","I'll visit Rome now.","I visit Rome."],0,"Plano feito: going to."),
81161:("will / won't","**Will + verbo** para previsões; **won't** para a negativa.",[("In the future, there {{will be}} flying cars.","No futuro, haverá carros voadores."),("We {{won't wash}} dishes.","Não lavaremos louça."),("It will {{probably}} rain.","Provavelmente vai chover."),("Robots {{will help}} us.","Robôs vão nos ajudar.")],"“Won't” é a forma curta de…",["will not","would not","was not"],0,"Won't = will not."),
920023:("past continuous + when","**Was/were + -ing** para a ação em andamento; **when** para a interrupção.",[("I {{was sailing}} on the deck.","Eu estava navegando no convés."),("I {{was sleeping}} when I saw it.","Eu estava dormindo quando vi."),("{{While}} I was running, it rained.","Enquanto eu corria, choveu."),("The crew {{was singing}} when it sank.","A tripulação estava cantando quando afundou.")],"Complete: “I was walking ___ it started to rain.”",["when","so","than"],0,"When marca a interrupção."),
81162:("I promise to / I will","Para prometer: **I promise to + verbo** ou **I will + verbo**.",[("I {{promise}} to be careful.","Prometo ter cuidado."),("I {{will keep}} my word.","Vou cumprir minha palavra."),("You can {{trust}} me.","Você pode confiar em mim."),("It's a {{deal}}.","Combinado.")],"Como prometer?",["I promise to help.","I promise helping.","I promised help."],0,"Promise to + verbo."),
81164:("would like to be","Emprego dos sonhos: **I would like to be + profissão**.",[("I {{would like to be}} a pilot.","Gostaria de ser piloto."),("She {{is}} a doctor.","Ela é médica."),("What is your {{dream job}}?","Qual é o seu emprego dos sonhos?"),("What {{would you like to be}}?","O que você gostaria de ser?")],"Complete: “I would like ___ be a chef.”",["to","for","of"],0,"Would like to be."),
81166:("I think / I believe","Para opinar: **I think + frase** ou **I believe + frase**. Para perguntar: **What do you think?**",[("{{I think}} the music is nice.","Acho a música boa."),("{{I believe}} he is honest.","Acredito que ele é honesto."),("{{I agree}} with you.","Concordo com você."),("{{What do you think}}?","O que você acha?")],"Como pedir a opinião de alguém?",["What do you think?","What you think?","How you think?"],0,"What do you think?"),
81167:("Concordar e discordar","**I agree** / **I disagree**. Para concordar: *So do I, Neither do I.*",[("{{I agree}} with you.","Concordo com você."),("{{I disagree}} with him.","Discordo dele."),("{{Maybe}} you are right.","Talvez você tenha razão."),("I like it. {{So do I}}.","Eu gosto. Eu também.")],"“I disagree” significa…",["Concordo.","Discordo.","Não sei."],1,"Disagree = discordar."),
81168:("Could you / Would you mind","**Could you + verbo?** ou **Would you mind + verbo-ing?**",[("{{Could you}} open the door?","Você poderia abrir a porta?"),("{{Would you mind}} closing the door?","Você se importaria de fechar a porta?"),("{{Thanks}} for your help.","Obrigado pela ajuda."),("Could you {{pass}} the tea?","Pode passar o chá?")],"Qual está certa?",["Would you mind close?","Would you mind closing?","Would you mind to close?"],1,"Would you mind + verbo-ing."),
920024:("Preposições de movimento","**Into** entra; **out of** sai; **through** atravessa por dentro; **across** atravessa por cima.",[("I ran {{across}} the river.","Corri através do rio."),("I walked {{through}} the park.","Caminhei pelo parque."),("He went {{into}} the house.","Ele entrou na casa."),("She came {{out of}} the tunnel.","Ela saiu do túnel.")],"Complete: “We walked ___ the tunnel.” (por dentro)",["across","through","over"],1,"Por dentro: through."),
81169:("Would you like to…?","Para convidar: **Would you like to + verbo?** Aceitar: *Yes, I'd love to.*",[("{{Would you like to}} come?","Você gostaria de vir?"),("Yes, {{I'd love to}}.","Sim, adoraria."),("{{I'm sorry}}, I can't.","Desculpe, não posso."),("It's a {{party}}!","É uma festa!")],"Como aceitar um convite?",["Yes, I'd love to.","Yes, I would not.","I love."],0,"I'd love to."),
81170:("I'd love to, but…","Para recusar: **I'd love to, but** + motivo.",[("{{I'd love to, but}} I'm busy.","Adoraria, mas estou ocupado."),("{{Maybe next time}}.","Talvez da próxima vez."),("I'd {{prefer not to}}.","Prefiro não."),("Thanks for the {{offer}}.","Obrigado pela oferta.")],"Qual recusa é educada?",["No.","I'd love to, but I'm busy.","I don't want."],1,"Recusa suave com motivo."),
81171:("I'd love to","Para aceitar: **Yes, I'd love to** ou **Sounds great!**",[("{{Would you like}} some tea?","Quer um chá?"),("Yes, {{I'd love to}}.","Sim, adoraria."),("{{Sounds great}}!","Parece ótimo!"),("A {{cup}} of tea, please.","Uma xícara de chá, por favor.")],"Complete: “Would you like cake?” — “Yes, I'd ___.”",["love to","like","want"],0,"I'd love to."),
81172:("because / so","**Because** dá o motivo; **so** dá o resultado.",[("I'm late {{because}} I was lost.","Estou atrasado porque me perdi."),("I was lost, {{so}} I'm late.","Me perdi, então estou atrasado."),("I was bored, {{so}} I lied.","Eu estava entediado, então menti."),("There is a {{wolf}}!","Há um lobo!")],"Complete: “I was tired, ___ I slept.”",["because","so","but"],1,"Cansaço → resultado: so."),
81173:("I'm sorry for","Desculpas: **I'm sorry for + algo** ou **I'm sorry I + passado**.",[("{{I'm sorry for}} my mistake.","Sinto muito pelo meu erro."),("{{It's my fault}}.","A culpa é minha."),("It {{won't happen again}}.","Não vai acontecer de novo."),("{{I'm sorry I'm}} late.","Desculpe o atraso.")],"Complete: “I'm sorry ___ the noise.”",["for","of","to"],0,"Sorry for + algo."),
81174:("Thank you for","Para agradecer: **Thank you for + algo**. Mais forte: **I'm so grateful for…**",[("{{Thank you for}} the gift.","Obrigado pelo presente."),("{{I'm very grateful}}.","Sou muito grato."),("{{You are}} very kind.","Você é muito gentil."),("Thanks for the {{dinner}}.","Obrigado pelo jantar.")],"Complete: “Thank you ___ your help.”",["to","for","of"],1,"Thank you for."),
81175:("Elogios","Elogie com **You look + adjetivo** ou **What a + adjetivo + substantivo!**",[("You {{look lovely}} today.","Você está linda hoje."),("{{What a beautiful}} letter!","Que carta linda!"),("You {{are}} very smart.","Você é muito inteligente."),("{{What a}} great voice!","Que voz ótima!")],"Qual é um elogio?",["You look lovely.","You look bad.","You look."],0,"You look + adjetivo positivo."),
920025:("enjoy + -ing / want to","**Enjoy** pede **-ing**; **want** e **hope** pedem **to + verbo**.",[("I {{enjoy cooking}} a lot.","Gosto muito de cozinhar."),("I {{want to learn}} kung fu.","Quero aprender kung fu."),("{{Stop eating}} now.","Pare de comer agora."),("I {{hope to visit}} China.","Espero visitar a China.")],"Qual está certa?",["I enjoy to swim.","I enjoy swimming.","I enjoy swim."],1,"Enjoy + -ing."),
81176:("is / has para descrever","Descreva com **He/She is + adjetivo** e **has + traço**.",[("He {{is tall}}.","Ele é alto."),("She {{has curly hair}}.","Ela tem cabelo cacheado."),("He {{has a beard}}.","Ele tem barba."),("She {{is}} young.","Ela é jovem.")],"Complete: “She ___ blue eyes.”",["is","has","are"],1,"Traço físico: has."),
81177:("Traços de caráter","Personalidade: **She is + adjetivo**. Pergunta: **What is she like?**",[("She {{is kind}}.","Ela é gentil."),("He {{isn't lazy}}.","Ele não é preguiçoso."),("{{What is she like}}?","Como ela é?"),("My cousin {{is}} very funny.","Meu primo é muito engraçado.")],"“What is she like?” pergunta…",["a personalidade","o endereço","a idade"],0,"What is she like? = como ela é."),
81178:("wearing","O que alguém veste agora: **is/are wearing**. Hábito: **wear**.",[("He {{is wearing}} a suit.","Ele está vestindo um terno."),("I {{wear}} a blue shirt.","Eu uso uma camisa azul."),("My shoes {{are new}}.","Meus sapatos são novos."),("She {{is wearing}} a hat.","Ela está usando um chapéu.")],"Complete: “Today she ___ a coat.”",["wears","is wearing","wear"],1,"Hoje, agora: is wearing."),
81179:("Adjetivo antes do nome","O adjetivo vem **antes** do substantivo e **não muda** no plural.",[("The stars {{are yellow}}.","As estrelas são amarelas."),("A {{bright}} star.","Uma estrela brilhante."),("I like {{striped}} shirts.","Gosto de camisas listradas."),("It's a {{dark}} night.","É uma noite escura.")],"Qual está certa?",["a shirt striped","a striped shirt","a stripeds shirt"],1,"Adjetivo + substantivo."),
81180:("Possessivos","**My, your, his, her, our, their** mostram de quem é.",[("{{My}} uncle has a farm.","Meu tio tem uma fazenda."),("{{Her}} aunt cooks well.","A tia dela cozinha bem."),("{{Our}} family is big.","Nossa família é grande."),("{{Their}} cousin lives far.","O primo deles mora longe.")],"Complete: “___ parents are kind.” (deles)",["Their","There","They"],0,"Deles: their."),
81181:("best friend","Amigos: **my best friend**; **I met him in…**; **since**.",[("He is {{my best friend}}.","Ele é meu melhor amigo."),("I {{met}} him in the forest.","Eu o conheci na floresta."),("We have been friends {{since}} spring.","Somos amigos desde a primavera."),("We {{share}} everything.","Dividimos tudo.")],"Complete: “We are friends ___ 2020.”",["for","since","ago"],1,"Ponto no tempo: since."),
81182:("there is / there are","**There is** (singular) e **there are** (plural) dizem que algo existe.",[("{{There is}} a window.","Há uma janela."),("{{There are}} two dogs.","Há dois cachorros."),("{{There isn't}} a garden.","Não há jardim."),("{{Is there}} a balcony?","Há uma varanda?")],"Complete: “___ two cats next door.”",["There is","There are","It is"],1,"Plural: there are."),
920026:("Advérbios de frequência","O advérbio vem **antes do verbo principal** e **depois do verbo be**.",[("I {{always}} wake up early.","Eu sempre acordo cedo."),("I {{sometimes}} run at night.","Às vezes corro à noite."),("I {{never}} drink soda.","Nunca bebo refrigerante."),("She is {{usually}} on time.","Ela geralmente chega na hora.")],"Qual está certa?",["She is never late.","She never is late.","Never she is late."],0,"Depois do be: is never."),
}
